  --color-primary-50:  #FBF5EA;   /* 골드 틴트 배경 */
  --color-primary-100: #F4E7C9;   /* subtle 강조 배경 */
  --color-primary-200: #EAD3A2;
  --color-primary-300: #E1C182;
  --color-primary-400: #DCBC74;
  --color-primary-500: #DBB86E;   /* Lindt Gold (기본) */
  --color-primary-600: #C39F52;   /* Old Gold, hover */
  --color-primary-700: #A07F3B;   /* active */
  --color-primary-800: #7A5F2A;
